"""os_chat.jsonl is generated by build_corpus.py, from the tables it reads."""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "SLM" / "tools"))
sys.path.insert(0, str(ROOT / "agent" / "tools"))

import build_corpus  # noqa: E402

DATASET = ROOT / "SLM" / "datasets" / "os_chat.jsonl"


def test_the_committed_chat_corpus_is_what_its_generator_produces():
    """A table it reads (device_drivers.py) can change after the corpus was built."""
    rows = [json.loads(line) for line in DATASET.read_text().splitlines()]
    assert rows == build_corpus.build(), "regenerate: python SLM/tools/build_corpus.py"
